using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using KianaPet;
class GradientTests {
 static List<string> checks=new List<string>();static void Check(bool b,string n){if(!b)throw new Exception(n);checks.Add(n);}static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static BitmapSource Cover(Color a,Color b){byte[] pixels=new byte[16*16*4];for(int y=0;y<16;y++)for(int x=0;x<16;x++){var c=x<8?a:b;int i=(y*16+x)*4;pixels[i]=c.B;pixels[i+1]=c.G;pixels[i+2]=c.R;pixels[i+3]=c.A;}var image=BitmapSource.Create(16,16,96,96,PixelFormats.Bgra32,null,pixels,64);image.Freeze();return image;}
 static double L(Color c){Func<byte,double> f=v=>v/255d<=.04045?v/255d/12.92:Math.Pow((v/255d+.055)/1.055,2.4);return .2126*f(c.R)+.7152*f(c.G)+.0722*f(c.B);}static double Contrast(Color a,Color b){return (Math.Max(L(a),L(b))+.05)/(Math.Min(L(a),L(b))+.05);}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);Store.Save(new Config{Walking=false,Gravity=false,LinkChatGPT=false,MusicEnabled=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false});var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var pet=new PetWindow(true);bool success=false;
 pet.Loaded+=async delegate{try{await Task.Delay(350);var settings=app.Windows.OfType<SettingsWindow>().Single();var art=Cover(Colors.CornflowerBlue,Colors.Coral);var pair=MusicGradient.SamplePair(art);Check(pair[0]!=pair[1],"多色封面提取不同的代表色");Check(pair.SequenceEqual(MusicGradient.SamplePair(art)),"同一封面取色结果稳定");var single=MusicGradient.SamplePair(Cover(Colors.Teal,Colors.Teal));Check(single[0]==single[1],"单色封面不凭空制造第二种色彩");Check(MusicGradient.SamplePair(Cover(Colors.Transparent,Colors.Transparent)).Length==2,"全透明封面有稳定回退");var config=new Config{MusicTintMode="unknown"};config.Validate();Check(config.MusicTintMode=="solid","旧配置和未知模式回退原有纯色");pet.Settings.MusicTintMode="background-gradient";pet.Settings.MusicTintStrength=75;Check(PreferenceTransfer.Import(PreferenceTransfer.Export(pet.Settings,false)).MusicTintMode=="background-gradient","渐变模式随偏好迁移");
 foreach(bool dark in new[]{false,true})foreach(string mode in new[]{"cover-gradient","background-gradient"}){Color background=PetPalette.Hex(dark?"#27262D":"#FFFFFF");Check(MusicGradient.Stops(pair,true,dark,false,100,mode).All(c=>c==background),mode+" "+dark+" 关闭取色恢复主题底色");Check(MusicGradient.Stops(pair,true,dark,true,0,mode).All(c=>c==background),mode+" "+dark+" 程度零恢复中性色");Check(MusicGradient.Stops(pair,false,dark,true,100,mode).All(c=>c==background),mode+" "+dark+" 缺少封面不残留旧颜色");var stops=MusicGradient.Stops(pair,true,dark,true,100,mode);Check(mode!="background-gradient"||stops[1]==background,"封面到背景模式终点匹配主题 "+dark);PetPalette.Dark=dark;Color secondary=PetPalette.Mix(PetPalette.Ink,PetPalette.Muted,.2);foreach(Color extreme in new[]{Colors.Black,Colors.White,Colors.Red,Colors.Blue,Colors.Lime}){var values=MusicGradient.Stops(new[]{extreme,extreme},true,dark,true,100,mode);Check(values.All(c=>Contrast(c,secondary)>=4.5),"极端封面仍保持文字对比 "+dark+" "+mode+" "+extreme);}}
 pet.Settings.Theme="light";pet.Settings.MusicTintMode="solid";pet.Settings.MusicTintStrength=80;pet.ApplySettings();var music=new MusicWindow(pet);music.Show();var state=new MusicState{Connected=true,Title="封面渐变示意",Artist="模拟封面 · 不控制播放",Playing=true,CanToggle=true,CanPrevious=true,CanNext=true};music.Refresh(state,"",art,false);await Task.Delay(400);Check(((Border)Field(music,"surface")).Background is SolidColorBrush,"原有纯色使用原画刷");settings.NavigateCategory("音乐","封面配色");var tabs=(TabControl)Field(settings,"settingsTabs");var page=(StackPanel)((ScrollViewer)((TabItem)tabs.SelectedItem).Content).Content;var picker=page.Children.OfType<ComboBox>().Single(c=>System.Windows.Automation.AutomationProperties.GetName(c)=="音乐栏配色样式");picker.SelectedIndex=1;Check(pet.Settings.MusicTintMode=="cover-gradient","下拉框立即保存双色渐变模式");settings.UpdateStatus();Check(((TextBlock)Field(settings,"musicColorPreviewText")).Text.StartsWith("示意配色"),"没有封面时设置预览明确标为示意");settings.Capture(Path.Combine(Store.Root,"gradient-settings.png"));music.Refresh(state,"",art,false);await Task.Delay(400);var fill=(LinearGradientBrush)((Border)Field(music,"surface")).Background;Check(fill.GradientStops[0].Color!=fill.GradientStops[1].Color,"真实音乐栏显示双色渐变");music.Capture(Path.Combine(Store.Root,"cover-gradient-light.png"));picker.SelectedIndex=2;music.Refresh(state,"",art,false);await Task.Delay(400);fill=(LinearGradientBrush)((Border)Field(music,"surface")).Background;Check(fill.GradientStops[1].Color==Colors.White,"真实浅色模式渐变到白色主题背景");music.Capture(Path.Combine(Store.Root,"background-gradient-light.png"));pet.Settings.Theme="dark";pet.ApplySettings();music.Refresh(state,"",art,false);await Task.Delay(400);music.Capture(Path.Combine(Store.Root,"background-gradient-dark.png"));Check(((LinearGradientBrush)((Border)Field(music,"surface")).Background).GradientStops[1].Color==PetPalette.Background,"深色主题渐变终点跟随切换: actual="+((LinearGradientBrush)((Border)Field(music,"surface")).Background).GradientStops[1].Color+" expected="+PetPalette.Background+" mode="+pet.Settings.MusicTintMode);pet.Settings.MusicTintMode="cover-gradient";pet.ApplySettings();music.Refresh(state,"",art,false);await Task.Delay(400);music.Capture(Path.Combine(Store.Root,"cover-gradient-dark.png"));Color prior=((LinearGradientBrush)((Border)Field(music,"surface")).Background).GradientStops[0].Color;music.Refresh(state,"",Cover(Colors.Gold,Colors.ForestGreen),false);await Task.Delay(90);Color midway=((LinearGradientBrush)((Border)Field(music,"surface")).Background).GradientStops[0].Color;await Task.Delay(320);Color final=((LinearGradientBrush)((Border)Field(music,"surface")).Background).GradientStops[0].Color;Check(prior!=midway&&midway!=final,"切歌颜色有连续过渡而非跳变");pet.Settings.ReduceMotion=true;pet.ApplySettings();music.Refresh(state,"",null,false);await Task.Delay(30);Check(((LinearGradientBrush)((Border)Field(music,"surface")).Background).GradientStops.All(s=>s.Color==PetPalette.Background),"减少动态与无封面时直接恢复中性色");pet.Settings.MusicTintMode="solid";pet.ApplySettings();music.Refresh(state,"",art,false);Check(((Border)Field(music,"surface")).Background is SolidColorBrush,"渐变可切回纯色");Check(((Button)Field(music,"toggle")).IsEnabled&&music.Height==88,"配色不改变播放按钮与紧凑高度");music.Close();success=true;
 }catch(Exception e){Store.Atomic("gradient-error.json",new{error=e.ToString()});}finally{Store.Atomic("gradient-tests.json",new{version="0.6.2",passed=success,checks=checks});pet.Close();}};app.Run(pet);return success?0:1;}
}
